 29. ADMIN CONFIG VIEW — FETCH AND SUBMIT LOGIC

The renderAdminConfigView function must implement the following exact fetchandsubmit pattern:

javascript
async function renderAdminConfigView() {
  const root = document.getElementById('app-root');
  root.innerHTML = '';
  renderNavBar();

  // Render skeleton while loading
  const skeleton = createSkeleton('100%', '400px');
  root.appendChild(skeleton);

  let configData;
  try {
    configData = await apiCall('GET', '/api/admin/config');
  } catch (err) {
    skeleton.remove();
    toast.error(`Failed to load configuration: ${err.detail ?? err}`);
    return;
  }
  skeleton.remove();

  // Track initial values to detect changes
  const initialValues = { ...configData };

  // Build form
  const form = document.createElement('form');
  form.setAttribute('novalidate', '');
  form.id = 'config-form';

  // ... (build all fields as described in Section 4.14)

  // On submit
  form.addEventListener('submit', async (e) => {
    e.preventDefault();
    const payload = {};

    // Only include changed fields
    // API key: only include if user typed a non-empty value
    const apiKeyInput = document.getElementById('config-openai-api-key');
    if (apiKeyInput.value.trim() !== '') {
      payload.openai_api_key = apiKeyInput.value.trim();
    }

    const modelSelect = document.getElementById('config-default-model');
    if (modelSelect.value !== initialValues.default_model) {
      payload.default_model = modelSelect.value;
    }

    // ... (same pattern for all other fields)

    if (Object.keys(payload).length === 0) {
      toast.info('No changes to save.');
      return;
    }

    // Validate min < max constraint client-side before submitting
    const minInput = document.getElementById('config-min-input-length');
    const maxInput = document.getElementById('config-max-input-length');
    if (minInput && maxInput) {
      const minVal = parseInt(minInput.value);
      const maxVal = parseInt(maxInput.value);
      if (!isNaN(minVal) && !isNaN(maxVal) && minVal >= maxVal) {
        Validator.showFieldError(
          minInput,
          'Minimum input length must be strictly less than maximum input length.'
        );
        return;
      }
    }

    const saveBtn = document.getElementById('config-save-btn');
    setButtonLoading(saveBtn, 'Saving...');

    try {
      const result = await apiCall('PUT', '/api/admin/config', payload);
      toast.success(`Saved: ${result.updated_keys.join(', ')}`);
      // Update initialValues to prevent re-submitting same changes
      for (const key of result.updated_keys) {
        if (key !== 'openai_api_key') {
          initialValues[key] = payload[key];
        }
      }
      // If API key was updated, update the configured badge
      if (payload.openai_api_key) {
        const badge = document.getElementById('api-key-badge');
        if (badge) {
          badge.textContent = 'Configured';
          badge.className = 'config-badge config-badge-ok';
        }
        apiKeyInput.value = '';  // Clear after save
      }
    } catch (err) {
      toast.error(`Save failed: ${err.detail ?? err}`);
    } finally {
      setButtonReady(saveBtn);
    }
  });

  root.appendChild(form);
}




 30. HISTORY VIEW — FULL FILTER AND SEARCH STATE MANAGEMENT

The renderHistoryView function must manage URLbased state for filters so that browser back/forward and page refresh preserve the filter state. Encode filter state in the hash query string:

#/history?page=2&status=completed&search=task+management&sort=created_at_desc

Parse these parameters from window.location.hash using a custom parseHashParams() function:

javascript
function parseHashParams() {
  const hash = window.location.hash;
  const queryIndex = hash.indexOf('?');
  if (queryIndex === -1) return {};
  const queryString = hash.substring(queryIndex + 1);
  const params = {};
  for (const pair of queryString.split('&')) {
    const [key, value] = pair.split('=').map(decodeURIComponent);
    if (key) params[key] = value ?? '';
  }
  return params;
}


When the user changes any filter or sorts, call:

javascript
function updateHistoryUrl(params) {
  const queryString = Object.entries(params)
    .filter(([, v]) => v !== '' && v !== null && v !== undefined)
    .map(([k, v]) => `${encodeURIComponent(k)}=${encodeURIComponent(v)}`)
    .join('&');
  const newHash = '#/history' + (queryString ? '?' + queryString : '');
  // Use replaceState to avoid polluting browser history with each filter change
  history.replaceState(null, '', newHash);
  // Re-render the table section only (not the full view)
  renderHistoryTable(params);
}


The renderHistoryTable function fetches the filtered data and replaces only the table and pagination elements, not the entire view. This avoids resetting the search input focus state on each filter change.



